var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var rows = Array.prototype.slice.call(root.querySelectorAll('.t212-rfqbook-row'));
var clock = root.querySelector('.t212-rfqbook-clock');
var fill = root.querySelector('.t212-rfqbook-fill');
var cover = root.querySelector('.t212-rfqbook-cover');
var hit = root.querySelector('.t212-rfqbook-hit');
var q = rows.map(function (r) {
  return { el: r, px: parseFloat(r.querySelector('.t212-rfqbook-px').textContent) };
});
var t = 4.8;
function paint() {
  var best = -Infinity, second = -Infinity;
  q.forEach(function (o) {
    if (o.px > best) { second = best; best = o.px; }
    else if (o.px > second) { second = o.px; }
  });
  q.forEach(function (o) {
    var isBest = o.px === best;
    o.el.classList.toggle('t212-rfqbook-best', isBest);
    o.el.querySelector('.t212-rfqbook-tag').textContent = isBest ? 'BEST' : '';
  });
  cover.textContent = ((best - second) * 10000).toFixed(1);
}
function reprice() {
  q.forEach(function (o) {
    if (Math.random() < 0.45) return;
    var prev = o.px;
    o.px = Math.max(1.08320, Math.min(1.08510, o.px + (Math.random() - 0.47) * 0.00014));
    var pxEl = o.el.querySelector('.t212-rfqbook-px');
    var arw = o.el.querySelector('.t212-rfqbook-arw');
    pxEl.textContent = o.px.toFixed(5);
    o.el.querySelector('.t212-rfqbook-sp').textContent = (0.3 + Math.random() * 1.1).toFixed(1) + 'p';
    var up = o.px >= prev;
    arw.classList.remove('t212-rfqbook-u', 't212-rfqbook-d');
    arw.classList.add(up ? 't212-rfqbook-u' : 't212-rfqbook-d');
    arw.textContent = up ? '▲' : '▼';
    if (reduce) return;
    pxEl.classList.remove('t212-rfqbook-u', 't212-rfqbook-d');
    void pxEl.offsetWidth;
    pxEl.classList.add(up ? 't212-rfqbook-u' : 't212-rfqbook-d');
  });
  paint();
}
var iv = setInterval(function () {
  if (!root.isConnected) { clearInterval(iv); clearInterval(cv); return; }
  reprice();
}, 1100);
var cv = setInterval(function () {
  if (!root.isConnected) { clearInterval(cv); return; }
  t -= 0.1;
  if (t <= 0) t = 5.0;
  clock.textContent = t.toFixed(1) + 's';
  fill.style.width = reduce ? '62%' : (t / 5 * 100).toFixed(1) + '%';
  clock.classList.toggle('t212-rfqbook-warn', t < 1.6);
}, 100);
hit.addEventListener('click', function () {
  hit.textContent = 'DONE ✓';
  hit.classList.add('t212-rfqbook-done');
  setTimeout(function () { hit.textContent = 'HIT BEST'; hit.classList.remove('t212-rfqbook-done'); }, 1400);
});
paint();

