var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var rows = Array.prototype.slice.call(root.querySelectorAll('.t212-allocpad-row'));
var run = root.querySelector('.t212-allocpad-run');
var TOTAL = 120000;
function fmt(n) { return Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
function count(el, from, to, ms) {
  if (reduce) { el.textContent = fmt(to); return; }
  var t0 = 0, live = true;
  function step(now) {
    if (!live) return;
    if (!t0) t0 = now;
    var p = Math.min(1, (now - t0) / ms), e = 1 - Math.pow(1 - p, 3);
    el.textContent = fmt(from + (to - from) * e);
    if (p < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
  setTimeout(function () { live = false; el.textContent = fmt(to); }, ms + 120);
}
function apply(weights, delay) {
  var max = Math.max.apply(null, weights);
  rows.forEach(function (r, i) {
    var w = weights[i];
    r.dataset.tgt = w;
    r.querySelector('.t212-allocpad-tg').textContent = w + '%';
    var shEl = r.querySelector('.t212-allocpad-sh');
    var from = parseFloat(shEl.textContent.replace(/,/g, '')) || 0;
    var to = Math.round(TOTAL * w / 100);
    var bar = r.querySelector('.t212-allocpad-fill');
    setTimeout(function () {
      bar.style.width = (w / max * 100).toFixed(1) + '%';
      count(shEl, from, to, 520);
    }, reduce ? 0 : delay + i * 80);
  });
}
function shuffle() {
  var raw = rows.map(function () { return 8 + Math.random() * 40; });
  var sum = raw.reduce(function (a, b) { return a + b; }, 0);
  var w = raw.map(function (v) { return Math.max(4, Math.round(v / sum * 100)); });
  var diff = 100 - w.reduce(function (a, b) { return a + b; }, 0);
  w[0] += diff;
  w.sort(function (a, b) { return b - a; });
  apply(w, 60);
}
apply(rows.map(function (r) { return parseFloat(r.dataset.tgt); }), 90);
run.addEventListener('click', shuffle);

