function openRows() {
  return rows.filter(function (r) { return r.dataset.sev !== 'ok' && r.dataset.ack !== '1'; });
}
function sync() {
  var o = openRows();
  num.textContent = String(o.length);
  lbl.textContent = o.length ? 'OPEN' : 'CLEAR';
  arc.style.strokeDashoffset = (C * (1 - o.length / rows.length)).toFixed(1);
  root.classList.toggle('t212-compflag-clear', o.length === 0);
  root.classList.toggle('t212-compflag-brc', o.some(function (r) { return r.dataset.sev === 'brc'; }));
}
rows.forEach(function (r, i) {
  if (!reduce) {
    r.style.opacity = '0';
    r.style.transform = 'translateX(-7px)';
    setTimeout(function () {
      r.style.transition = 'opacity .3s ease,transform .34s cubic-bezier(.2,.9,.25,1)';
      r.style.opacity = '';
      r.style.transform = 'none';
    }, 80 + i * 70);
  }
  r.addEventListener('click', function () {
    if (r.dataset.sev === 'ok') return;
    var acked = r.dataset.ack === '1';
    r.dataset.ack = acked ? '0' : '1';
    r.querySelector('.t212-compflag-chip').textContent = acked ? r.dataset.sev.toUpperCase() : 'ACK';
    sync();
  });
});
setTimeout(sync, reduce ? 0 : 220);

