var cells = Array.prototype.slice.call(root.querySelectorAll('.t212-setmatrix-cell'));
var read = root.querySelector('.t212-setmatrix-read');
var failEl = root.querySelector('.t212-setmatrix-fail');
var pendEl = root.querySelector('.t212-setmatrix-pend');
var NAMES = { ok: 'SETTLED', pend: 'PENDING', fail: 'FAIL', na: 'NO ACTIVITY' };
function label(c) { return c.parentNode.querySelector('.t212-setmatrix-rl').textContent; }
function detail(c) {
  return label(c) + ' ' + c.dataset.d + ' SEP · ' + NAMES[c.dataset.s] + ' · ' + c.dataset.n + ' tr';
}
function tally() {
  var f = 0, p = 0;
  cells.forEach(function (c) {
    if (c.dataset.s === 'fail') f++;
    if (c.dataset.s === 'pend') p++;
  });
  failEl.textContent = f + ' FAIL';
  pendEl.textContent = p + ' PEND';
}
cells.forEach(function (c) {
  c.setAttribute('aria-label', detail(c));
  function show() { paused = Date.now() + 4000; cells.forEach(function (x) { x.classList.remove('t212-setmatrix-scan'); }); read.textContent = detail(c); }
  c.addEventListener('mouseenter', show);
  c.addEventListener('focus', show);
  c.addEventListener('click', show);
});
var paused = 0, idx = 0;
var scan = setInterval(function () {
  if (!root.isConnected) { clearInterval(scan); clearInterval(prog); return; }
  if (Date.now() < paused) return;
  cells.forEach(function (x) { x.classList.remove('t212-setmatrix-scan'); });
  var c = cells[idx % cells.length];
  idx++;
  c.classList.add('t212-setmatrix-scan');
  read.textContent = detail(c);
}, 1500);
var prog = setInterval(function () {
  if (!root.isConnected) { clearInterval(prog); return; }
  var pend = cells.filter(function (c) { return c.dataset.s === 'pend'; });
  if (pend.length > 2) {
    var c = pend[Math.floor(Math.random() * pend.length)];
    c.dataset.s = 'ok';
    c.setAttribute('aria-label', detail(c));
    c.classList.remove('t212-setmatrix-just');
    void c.offsetWidth;
    c.classList.add('t212-setmatrix-just');
  } else {
    cells.filter(function (c) { return c.dataset.s === 'ok'; }).slice(-4).forEach(function (c) {
      c.dataset.s = 'pend';
      c.setAttribute('aria-label', detail(c));
    });
  }
  tally();
}, 3400);
