function grp(n) { return Math.abs(Math.round(n)).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
function sgn(n) { return (n >= 0 ? '+' : '-') + grp(n); }
function flash(el, up) {
  if (reduce) return;
  el.classList.remove('t212-postape-fu', 't212-postape-fd');
  void el.offsetWidth;
  el.classList.add(up ? 't212-postape-fu' : 't212-postape-fd');
}
