var head = root.querySelectorAll('.t212-postape-h')[4];
var mode = 'usd';
function plOf(r) { return (parseFloat(r.dataset.last) - parseFloat(r.dataset.avg)) * parseFloat(r.dataset.pos); }
function costOf(r) { return Math.abs(parseFloat(r.dataset.pos)) * parseFloat(r.dataset.avg); }
function pct(n) { return (n >= 0 ? '+' : '-') + Math.abs(n).toFixed(2) + '%'; }
function cell(r) {
  var v = plOf(r);
  return mode === 'usd' ? sgn(v) : pct(v / costOf(r) * 100);
