  el.classList.toggle('t212-postape-up', v >= 0);
  el.classList.toggle('t212-postape-dn', v < 0);
}
function net() {
  var pl = 0, cost = 0;
  rows.forEach(function (r) { pl += plOf(r); cost += costOf(r); });
