  read.textContent = 'R' + (Math.floor(i / COLS) + 1) + '·C' + (i % COLS + 1) + ' ' + HEADS[i % COLS] + ' = ' + val(cells[i]);
}
function move(i, doFocus) {
  i = Math.max(0, Math.min(cells.length - 1, i));
  cells[cur].setAttribute('tabindex', '-1');
  cells[cur].classList.remove('t212-keygrid-cur');
  cur = i;
  cells[cur].setAttribute('tabindex', '0');
  cells[cur].classList.add('t212-keygrid-cur');
  if (doFocus) cells[cur].focus();
  say(cur);
}
grid.addEventListener('keydown', function (e) {
  var r = Math.floor(cur / COLS), c = cur % COLS, n = null;
  if (e.key === 'ArrowRight') n = c < COLS - 1 ? cur + 1 : cur;
  else if (e.key === 'ArrowLeft') n = c > 0 ? cur - 1 : cur;
  else if (e.key === 'ArrowDown') n = r < ROWS - 1 ? cur + COLS : cur;
  else if (e.key === 'ArrowUp') n = r > 0 ? cur - COLS : cur;
  else if (e.key === 'Home') n = r * COLS;
  else if (e.key === 'End') n = r * COLS + COLS - 1;
  else if (e.key === 'Enter' || e.key === ' ') {
    e.preventDefault();
